const raw = {{apiResponse}};

if (!raw) {
  await setVariable("userLanguage", "");
  return;
}

const text = Array.isArray(raw)
  ? String(raw[raw.length - 1])
  : String(raw);

try {
  const parsed = JSON.parse(text);

  const language = parsed?.results?.[0]?.language || "";

  await setVariable("userLanguage", language);
} catch (err) {
  await setVariable("userLanguage", "");
}

