try {                                                                                                                                                      

    // setApiResponse already contains the text from the webhook mapping                                                                                     

    const responseText = {{setApiResponse}};                                                                                                                 

    // Remove markdown code blocks if present                                                                                                                

    const jsonText = responseText.replace(/```json/g, '').replace(/```/g, '').trim();                                                                        

    // Parse JSON                                                                                                                                            

    const result = JSON.parse(jsonText);                                                                                                                     

    // Set variables                                                                                                                                         

    setVariable('sentiment', result.sentiment);                                                                                                              

    setVariable('emotion', result.emotion);                                                                                                                  

    setVariable('confidenceScore', result.confidence);                                                                                                       

    setVariable('keyTopics', result.topics);                                                                                                                 

    setVariable('chatSummary', result.summary);                                                                                                              

  } catch(err) {                                                                                                                                             

    console.error('Parsing error:', err.message);                                                                                                            

    // Fallback values on error                                                                                                                              

    setVariable('sentiment', 'neutral');                                                                                                                     

    setVariable('emotion', 'neutral');                                                                                                                       

    setVariable('confidenceScore', 50);                                                                                                                      

    setVariable('keyTopics', 'unknown');                                                                                                                     

    setVariable('chatSummary', 'Analysis unavailable: ' + err.message);                                                                                      

  }

const raw = {{chatBotReponse}}

if (!raw) {
  await setVariable("chatBotReponse", "");
  return;
}

const text = Array.isArray(raw) ? String(raw[raw.length - 1]) : String(raw);
const start = text.indexOf("{");
const end = text.lastIndexOf("}");

if (start === -1 || end <= start) {
  await setVariable("chatBotReponse", text);
  return;
}

let customerResponse = text;

try {
  const parsed = JSON.parse(text.slice(start, end + 1));
  if (typeof parsed.customerResponse === "string") {
    customerResponse = parsed.customerResponse;
  }
} catch (err) {
  customerResponse = text;
}

await setVariable("chatBotReponse", customerResponse);

const raw = {{response}}

if (!raw) {
  await setVariable("collection", "");
  return;
}

const data = typeof raw === "string" ? JSON.parse(raw) : raw;

const message = data?.data?.message || "";

await setVariable("collection", message);

const raw = {{chatBotReponse}};

if (!raw) {
  await setVariable("chatBotReponse", "");
  await setVariable("requiresTransactionRetrieval", false);
  return;
}

const text = Array.isArray(raw)
  ? String(raw[raw.length - 1])
  : String(raw);

const start = text.indexOf("{");
const end = text.lastIndexOf("}");

if (start === -1 || end <= start) {
  await setVariable("chatBotReponse", text);
  await setVariable("requiresTransactionRetrieval", false);
  return;
}

let customerResponse = text;
let requiresTransactionRetrieval = false;

try {
  const parsed = JSON.parse(text.slice(start, end + 1));

  if (typeof parsed.customerResponse === "string") {
    customerResponse = parsed.customerResponse;
  }

  if (typeof parsed.agentContext?.requiresTransactionRetrieval === "boolean") {
    requiresTransactionRetrieval =
      parsed.agentContext.requiresTransactionRetrieval;
  }

} catch (err) {
  customerResponse = text;
}

await setVariable("chatBotReponse", customerResponse);
await setVariable(
  "requiresTransactionRetrieval",
  requiresTransactionRetrieval
);

