const raw = {{cardd}}

if (!raw) {
  await setVariable("cardd", "");
  return;
}

const text = Array.isArray(raw) ? String(raw[raw.length - 1]) : String(raw);

let selectedTransaction = text;

if (text.toLowerCase().includes("select transaction")) {
  const match = text.match(/transaction\s+(\d+)/i);

  if (match) {
    selectedTransaction = `Transaction ${match[1]}`;
  }
}

await setVariable("cardd", selectedTransaction);

